def search(self, keyword):
    """
    Search for items in the data that contain the given keyword.
    :param keyword: str, the keyword to search for
    :return: dict, containing search information such as total results and matching items
    >>> page_util = PageUtil([1, 2, 3, 4], 1)
    >>> page_util.search("1")
    >>> search_info = {
    >>>     "keyword": "1",
    >>>     "total_results": 1,
    >>>     "total_pages": 1,
    >>>     "results": [1]
    >>> }
    """
    keyword_str = str(keyword).lower() if keyword else ""
    filtered_data = []

    for item in self.data:
        try:
            item_str = str(item).lower()
        except Exception:
            continue

        if keyword_str == "":
            filtered_data.append(item)
        elif keyword_str in item_str:
            filtered_data.append(item)

    # Calculate pagination info for filtered results
    total_filtered_items = len(filtered_data)
    filtered_page_size = self.page_size

    if total_filtered_items > 0:
        filtered_total_pages = (total_filtered_items + filtered_page_size - 1) // filtered_page_size
    else:
        filtered_total_pages = 0

    return {
        "keyword": keyword,
        "total_results": total_filtered_items,
        "total_pages": filtered_total_pages,
        "results": filtered_data
    }

